import{D as s,o as l,c as i,k as a,a as r,G as n,w as d,a2 as p}from"./chunks/framework.n5RLHRfo.js";const u=JSON.parse('{"title":"Post-Effect Overview","description":"The Post-Effect system applies screen-space lighting, color grading, lens effects, and anti-aliasing to the final output image via a compute-shader pipe...","frontmatter":{"title":"Post-Effect Overview","order":9},"headers":[],"relativePath":"en/post-effect/index.md","filePath":"en/post-effect/index.md","lastUpdated":1794650641000}'),m={name:"en/post-effect/index.md"},R=Object.assign(m,{setup(f){const t=`
    graph TB
        subgraph HDR ["1. HDR Built-in & Temporal Phase"]
            direction TB
            SA["SkyAtmosphere / SSAO / SSR / Fog / HeightFog"]:::pipelineNode
            TAA["TAA / AutoExposure"]:::pipelineNode
            OPT["DOF / Bloom / LensFlare"]:::pipelineNode
            SA --> TAA --> OPT
        end

        subgraph LDR ["2. Tone Mapping & LDR Post-Processing Phase"]
            direction TB
            TM["ToneMappingManager (HDR → LDR)"]:::pipelineNode
            BLDR["Built-in LDR (ChromaticAberration / LensDistortion / Vignetting / FilmGrain)"]:::pipelineNode
            ULDR["PostEffectManager (Custom LDR Chain)"]:::pipelineNode
            TM --> BLDR --> ULDR
        end

        subgraph Final ["3. Debugger Isolation & Final Output Phase"]
            direction TB
            DBG["DebuggerRenderer (Overlay Pass)"]:::pipelineNode
            AA["FinalRender (Fused FXAA / TAA CAS)"]:::pipelineNode
            DBG --> AA
        end

        HDR --> LDR --> Final

    classDef pipelineNode fill:#fafafa,stroke:#e4e4e7,color:#27272a,stroke-width:1px;
    style HDR fill:#e4e4e7,stroke:#d4d4d8,stroke-width:1px,color:#18181b;
    style LDR fill:#e4e4e7,stroke:#d4d4d8,stroke-width:1px,color:#18181b;
    style Final fill:#f4f4f5,stroke:#e4e4e7,stroke-width:1px,color:#27272a;
`;return(P,e)=>{const o=s("MermaidResponsive"),c=s("ClientOnly");return l(),i("div",null,[e[0]||(e[0]=a("h1",{id:"post-effect",tabindex:"-1"},[r("Post-Effect "),a("a",{class:"header-anchor",href:"#post-effect","aria-label":'Permalink to "Post-Effect"'},"​")],-1)),e[1]||(e[1]=a("p",null,"The Post-Effect system applies screen-space lighting, color grading, lens effects, and anti-aliasing to the final output image via a compute-shader pipeline after the 3D scene's G-Buffer rendering is complete.",-1)),n(c,null,{default:d(()=>[n(o,{definition:t})]),_:1}),e[2]||(e[2]=p('<h2 id="_1-control-interface" tabindex="-1">1. Control Interface <a class="header-anchor" href="#_1-control-interface" aria-label="Permalink to &quot;1. Control Interface&quot;">​</a></h2><p><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/View3D.html"><code>View3D</code></a> provides three manager properties depending on the post-processing purpose, while actual pipeline execution and texture pooling (<a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/Core/classes/PostEffectTexturePool.html"><code>PostEffectTexturePool</code></a>) are centrally managed by <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/classes/PostEffectManager.html"><code>PostEffectManager</code></a>.</p><ul><li><strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/classes/BuiltInEffectManager.html"><code>view.builtInEffectManager</code></a></strong>: Controls the 12 built-in system effects (<a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSAO.html"><code>SSAO</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSR.html"><code>SSR</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Fog.html"><code>Fog</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/HeightFog.html"><code>HeightFog</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/AutoExposure.html"><code>AutoExposure</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/DOF.html"><code>DOF</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Bloom.html"><code>Bloom</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/LensFlare.html"><code>LensFlare</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/ChromaticAberration.html"><code>ChromaticAberration</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/LensDistortion.html"><code>LensDistortion</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Vignetting.html"><code>Vignetting</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/FilmGrain.html"><code>FilmGrain</code></a>) and their parameters.</li><li><strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/classes/PostEffectManager.html"><code>view.postEffectManager</code></a></strong>: Manages custom user LDR effect chains (<code>addEffect</code>, <code>removeEffect</code>) and executes the entire post-processing pipeline.</li><li><strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/ToneMapping/classes/ToneMappingManager.html"><code>view.toneMappingManager</code></a></strong>: Controls the tone mapping algorithm (<code>mode</code>), <code>contrast</code>, and <code>brightness</code> that map HDR data into the display output range (LDR).</li></ul><hr><h2 id="_2-rendering-pipeline-execution-order" tabindex="-1">2. Rendering Pipeline Execution Order <a class="header-anchor" href="#_2-rendering-pipeline-execution-order" aria-label="Permalink to &quot;2. Rendering Pipeline Execution Order&quot;">​</a></h2><p><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/classes/PostEffectManager.html"><code>PostEffectManager</code></a> executes post-processing in the following 3 phases to preserve physical accuracy and image quality:</p><ol><li><strong>HDR Built-in &amp; Temporal Phase</strong><ul><li>Sequentially executes <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/SkyAtmosphere.html"><code>SkyAtmosphere</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSAO.html"><code>SSAO</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSR.html"><code>SSR</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Fog.html"><code>Fog</code></a>, and <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/HeightFog.html"><code>HeightFog</code></a> using the scene&#39;s HDR color and G-Buffer (depth, normal, motion vector).</li><li>When <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/TAA.html"><code>TAA</code></a> is enabled, temporal accumulation is performed in HDR space prior to tone mapping, followed by <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/AutoExposure.html"><code>AutoExposure</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/DOF.html"><code>DOF</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Bloom.html"><code>Bloom</code></a>, and <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/LensFlare.html"><code>LensFlare</code></a>.</li></ul></li><li><strong>Tone Mapping &amp; LDR Post-Processing Phase</strong><ul><li><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/ToneMapping/classes/ToneMappingManager.html"><code>ToneMappingManager</code></a> converts the HDR result into <code>rgba8unorm</code> LDR color space.</li><li>Built-in LDR effects (<a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/ChromaticAberration.html"><code>ChromaticAberration</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/LensDistortion.html"><code>LensDistortion</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Vignetting.html"><code>Vignetting</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/FilmGrain.html"><code>FilmGrain</code></a>) run first, followed by the custom LDR effect chain registered via <code>view.postEffectManager.addEffect()</code>.</li></ul></li><li><strong>Debugger Isolation &amp; Final Output Phase</strong><ul><li><code>DebuggerRenderer</code> renders grids and debug gizmos in an isolated overlay pass after all post-processing to avoid interfering with <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/AutoExposure.html"><code>AutoExposure</code></a> or <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/DOF.html"><code>DOF</code></a>.</li><li>Completes the final swap-chain image through <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/FXAA.html"><code>FXAA</code></a> or <code>TAA CAS</code> sharpening integrated into <code>FinalRender</code>.</li></ul></li></ol><hr><h2 id="_3-core-components" tabindex="-1">3. Core Components <a class="header-anchor" href="#_3-core-components" aria-label="Permalink to &quot;3. Core Components&quot;">​</a></h2><ol><li><strong><a href="./builtin-effects.html">Built-in Effects</a></strong>: Control the 12 standard built-in effects such as <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSAO.html"><code>SSAO</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/SSR.html"><code>SSR</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Fog.html"><code>Fog</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/AutoExposure.html"><code>AutoExposure</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/DOF.html"><code>DOF</code></a>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/Bloom.html"><code>Bloom</code></a>, and <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/namespaces/BuiltIn/classes/LensFlare.html"><code>LensFlare</code></a> via <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/PostEffect/classes/BuiltInEffectManager.html"><code>BuiltInEffectManager</code></a>.</li><li><strong><a href="./tone-mapping.html">Tone Mapping</a></strong>: Map HDR scene colors and exposure into the LDR display range via <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/ToneMapping/classes/ToneMappingManager.html"><code>ToneMappingManager</code></a>.</li><li><strong><a href="./general-effects.html">General Effects</a></strong>: Build custom LDR filter chains such as blur, color adjustments, sharpen, and convolution via <code>addEffect()</code>.</li></ol><hr><h2 id="related-examples" tabindex="-1">Related Examples <a class="header-anchor" href="#related-examples" aria-label="Permalink to &quot;Related Examples&quot;">​</a></h2><ul><li><a href="/RedGPU/examples/postEffect/builtIn/screenSpace/ssao/" target="_blank" rel="noopener noreferrer">SSAO (Screen Space Ambient Occlusion)</a></li><li><a href="/RedGPU/examples/postEffect/builtIn/screenSpace/ssr/" target="_blank" rel="noopener noreferrer">SSR (Screen Space Reflection)</a></li><li><a href="/RedGPU/examples/postEffect/builtIn/lens/dof/" target="_blank" rel="noopener noreferrer">Depth of Field (DoF)</a></li><li><a href="/RedGPU/examples/postEffect/builtIn/lens/bloom/" target="_blank" rel="noopener noreferrer">Bloom</a></li><li><a href="/RedGPU/examples/postEffect/builtIn/lens/lensFlareSkyAtmosphere/" target="_blank" rel="noopener noreferrer">Lens Flare (SkyAtmosphere)</a></li><li><a href="/RedGPU/examples/postEffect/builtIn/lens/lensFlareSkyBox/" target="_blank" rel="noopener noreferrer">Lens Flare (SkyBox)</a></li></ul><hr><p><a href="./builtin-effects.html">Next Step: Learn Built-in Effects</a></p>',15))])}}});export{u as __pageData,R as default};
